"""policy.ini (docs/policy.md)."""

import re
from datetime import timedelta
from pathlib import Path

from logkeep import streams
from logkeep.errors import DataError

BUILTIN = {
    "max_size": None,
    "max_age": None,
    "naming": "numbered",
    "offset": timedelta(0),
    "compress_after": 1,
    "keep": 5,
    "keep_days": None,
}

_SIZE = re.compile(r"([0-9]+)([KMGkmg]?)\Z")
_DURATION = re.compile(r"([0-9]+)([mhd])\Z")
_OFFSET = re.compile(r"([+-])([0-9]{2}):([0-9]{2})\Z")
_INT = re.compile(r"[0-9]+\Z")
_UNITS = {"": 1, "k": 1024, "m": 1024**2, "g": 1024**3}


def _bad(msg):
    return DataError("policy", f"policy.ini: {msg}")


def _size(v):
    if v == "off":
        return None
    m = _SIZE.match(v)
    if not m:
        raise _bad(f"bad size {v!r}")
    return int(m.group(1)) * _UNITS[m.group(2).lower()]


def _duration(v):
    if v == "off":
        return None
    m = _DURATION.match(v)
    if not m:
        raise _bad(f"bad duration {v!r}")
    return timedelta(**{{"m": "minutes", "h": "hours", "d": "days"}[m.group(2)]: int(m.group(1))})


def _naming(v):
    if v not in ("numbered", "dated"):
        raise _bad(f"bad naming {v!r}")
    return v


def _offset(v):
    m = _OFFSET.match(v)
    if not m or int(m.group(2)) > 23 or int(m.group(3)) > 59:
        raise _bad(f"bad offset {v!r}")
    d = timedelta(hours=int(m.group(2)), minutes=int(m.group(3)))
    return -d if m.group(1) == "-" else d


def _count(minimum):
    def parse(v):
        if not _INT.match(v) or int(v) < minimum:
            raise _bad(f"bad number {v!r}")
        return int(v)

    return parse


def _keep_days(v):
    return None if v == "off" else _count(1)(v)


PARSERS = {
    "max_size": _size,
    "max_age": _duration,
    "naming": _naming,
    "offset": _offset,
    "compress_after": _count(0),
    "keep": _count(1),
    "keep_days": _keep_days,
}


def load(path: Path):
    """Returns (defaults, {stream name: settings given in its section})."""
    defaults = {}
    per_stream = {}
    if not path.exists():
        return defaults, per_stream
    try:
        text = path.read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError) as e:
        raise _bad(str(e)) from None
    current = None
    seen_defaults = False
    for raw in text.splitlines():
        line = raw.strip()
        if not line or line[0] in "#;":
            continue
        if line[0] == "[":
            if line == "[defaults]":
                if seen_defaults:
                    raise _bad("section [defaults] twice")
                seen_defaults = True
                current = defaults
            elif line.startswith("[stream ") and line.endswith("]"):
                name = line[8:-1]
                if not streams.valid(name):
                    raise _bad(f"bad section {line}")
                if name in per_stream:
                    raise _bad(f"section {line} twice")
                current = per_stream[name] = {}
            else:
                raise _bad(f"unknown section {line}")
            continue
        if current is None or "=" not in line:
            raise _bad(f"bad line {line!r}")
        key, _, value = line.partition("=")
        key, value = key.strip(), value.strip()
        if key not in PARSERS:
            raise _bad(f"unknown key {key!r}")
        if key in current:
            raise _bad(f"key {key} twice")
        current[key] = PARSERS[key](value)
    return defaults, per_stream


def settings(defaults, per_stream, name):
    out = dict(BUILTIN)
    out.update(defaults)
    out.update(per_stream.get(name, {}))
    return out
