"""rotate (docs/rotate.md)."""

import gzip
import re
from datetime import date, datetime, timedelta, timezone

from logkeep import dates, policy, streams
from logkeep.errors import DataError, Refused

_TIME = re.compile(
    r"([0-9]{4})-([0-9]{2})-([0-9]{2})[T ]([0-9]{2}):([0-9]{2}):([0-9]{2})(?:[.,]([0-9]+))?"
    r"(Z|[+-][0-9]{2}(?::?[0-9]{2})?)?\Z"
)
_LEGACY = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}\Z")


def parse_time(text, legacy_ok=False):
    """A time of data.md section 2 as an aware datetime, or None."""
    if not isinstance(text, str):
        return None
    m = _TIME.match(text)
    if not m:
        return None
    y, mo, d, h, mi, s, frac, tz = m.groups()
    if tz is None:
        if not (legacy_ok and _LEGACY.match(text)):
            return None
        zone = timezone.utc
    elif tz == "Z":
        zone = timezone.utc
    else:
        digits = tz[1:].replace(":", "")
        oh, om = int(digits[:2]), int(digits[2:] or 0)
        if oh > 23 or om > 59:
            return None
        delta = timedelta(hours=oh, minutes=om)
        zone = timezone(-delta if tz[0] == "-" else delta)
    try:
        return datetime(int(y), int(mo), int(d), int(h), int(mi), int(s),
                        int((frac or "0")[:6].ljust(6, "0")), tzinfo=zone)
    except ValueError:
        return None


def _validate_state(entry):
    if "opened" in entry and parse_time(entry["opened"], True) is None:
        raise DataError("state", "bad opened time")
    if "archives" in entry:
        arch = entry["archives"]
        if not isinstance(arch, dict):
            raise DataError("state", "archives is not an object")
        for v in arch.values():
            if parse_time(v, True) is None:
                raise DataError("state", "bad archive time")
    if "rotations" in entry:
        r = entry["rotations"]
        if isinstance(r, bool) or not isinstance(r, int) or r < 0:
            raise DataError("state", "bad rotations")


class Archive:
    def __init__(self, name, key, gz, new=False):
        self.name = name  # file name before the run
        self.key = key  # age key: larger is newer for dated, smaller for numbered
        self.gz = gz
        self.new = new
        self.time = None
        self.time_text = None
        self.final = None
        self.compress = False
        self.removed = False


def _find_archives(logs, name, naming):
    if naming == "numbered":
        rx = re.compile(re.escape(name) + r"\.log\.([1-9][0-9]*)(\.gz)?\Z")
    else:
        rx = re.compile(re.escape(name) + r"\.log\.([0-9]{4}-[0-9]{2}-[0-9]{2})(?:\.([2-9]|[1-9][0-9]+))?(\.gz)?\Z")
    found = []
    if not logs.is_dir():
        return found
    for p in logs.iterdir():
        m = rx.match(p.name)
        if not m or not p.is_file():
            continue
        if naming == "numbered":
            found.append(Archive(p.name, (int(m.group(1)),), bool(m.group(2))))
        else:
            try:
                day = date.fromisoformat(m.group(1))
            except ValueError:
                continue
            k = int(m.group(2)) if m.group(2) else 1
            found.append(Archive(p.name, (day, k), bool(m.group(3))))
    return found


def _place(a):
    return a.key


def run(ctx, names, dry_run, force):
    """names: stream names given (list) or empty for all."""
    defaults, per_stream = policy.load(ctx.policy_path)
    state = ctx.state
    existing = set(streams.active(ctx.data)) | set(per_stream)
    for n in existing:
        entry = state["streams"].get(n)
        if entry is not None:
            _validate_state(entry)
    if names:
        for n in names:
            if n not in existing:
                raise Refused("unknown-stream", f"no stream {n}")
        todo = sorted(set(names))
    else:
        todo = sorted(existing)

    logs = streams.logs_dir(ctx.data)
    plans = []
    for n in todo:
        cfg = policy.settings(defaults, per_stream, n)
        archives = _find_archives(logs, n, cfg["naming"])
        seen = set()
        for a in archives:
            base = a.name[:-3] if a.gz else a.name
            if base in seen:
                raise DataError("archives", f"{base} exists twice")
            seen.add(base)
        plans.append((n, cfg, archives))

    now = ctx.now
    out = []
    totals = [0, 0, 0]
    writes = []  # (removals, reads/targets)
    removals = []
    moves = []  # (source path or None, bytes or None, target path, compress)
    new_state = {}
    for n, cfg, archives in plans:
        entry = state["streams"].get(n, {})
        times = entry.get("archives", {}) if isinstance(entry.get("archives", {}), dict) else {}
        for a in archives:
            if a.name in times:
                a.time_text = times[a.name]
                a.time = parse_time(a.time_text, True)
        log = streams.log_path(ctx.data, n)
        has_log = log.is_file()
        opened = entry.get("opened")
        why = None
        if not has_log:
            what = "no log"
        else:
            size = log.stat().st_size
            if size == 0:
                what = "empty"
            elif force:
                what, why = "rotate (forced)", True
            else:
                what = "not due"
                if cfg["max_size"] is not None and size >= cfg["max_size"]:
                    what = "rotate (size)"
                elif cfg["max_age"] is not None:
                    t = parse_time(opened, True) if opened is not None else _first_line_time(log)
                    if t is not None and now - t >= cfg["max_age"]:
                        what = "rotate (age)"
            why = what.startswith("rotate")
        rotated = bool(why)
        out.append(f"{n}: {what}")

        newa = None
        if rotated:
            if cfg["naming"] == "numbered":
                newa = Archive(None, (0,), False, True)
            else:
                day = now.astimezone(timezone(cfg["offset"])).date()
                ks = [a.key[1] for a in archives if a.key[0] == day]
                k = max(ks) + 1 if ks else None
                newa = Archive(None, (day, k or 1), False, True)
                newa.dayname = f"{n}.log.{day.isoformat()}" + (f".{k}" if k else "")
            newa.time = now
            newa.time_text = dates.stamp(now)
            archives = archives + [newa]
        if cfg["naming"] == "numbered":
            ordered = sorted(archives, key=lambda a: a.key)
        else:
            ordered = sorted(archives, key=lambda a: a.key, reverse=True)
        keep_days = cfg["keep_days"]
        for pos, a in enumerate(ordered, 1):
            if pos > cfg["keep"]:
                a.removed = True
            elif keep_days is not None and a.time is not None and now - a.time >= timedelta(days=keep_days):
                a.removed = True
        remaining = [a for a in ordered if not a.removed]
        for i, a in enumerate(remaining, 1):
            a.compress = i > cfg["compress_after"] and not a.gz
            gz = a.gz or a.compress
            if cfg["naming"] == "numbered":
                a.final = f"{n}.log.{i}" + (".gz" if gz else "")
            else:
                base = a.dayname if a.new else (a.name[:-3] if a.gz else a.name)
                a.final = base + (".gz" if gz else "")
        for a in remaining:
            if a.new:
                out.append(f"  new {a.final}")
            elif a.final != a.name:
                out.append(f"  {a.final} <- {a.name}")
            else:
                out.append(f"  {a.name}")
        for a in ordered:
            if a.removed:
                nm = a.name or a.dayname
                out.append(f"  remove {nm}")
        totals[0] += rotated
        totals[1] += sum(a.removed for a in ordered)
        totals[2] += sum(a.compress for a in remaining)

        # file operations
        for a in ordered:
            if a.removed:
                if not a.new:
                    removals.append(logs / a.name)
            elif a.new:
                moves.append((log, None, logs / a.final, a.compress))
            elif a.final != a.name:
                moves.append((logs / a.name, None, logs / a.final, a.compress))
        if rotated:
            moves.append(("truncate", None, log, False))
        ne = {}
        if opened is not None or rotated:
            ne["opened"] = dates.stamp(now) if rotated else opened
        ne["rotations"] = entry.get("rotations", 0) + (1 if rotated else 0)
        ne["archives"] = {a.final: a.time_text for a in remaining if a.time_text is not None}
        new_state[n] = ne

    out.append(f"{totals[0]} rotated, {totals[1]} removed, {totals[2]} compressed")
    if dry_run:
        out.append("dry run: nothing written")
        return out

    # read everything first, then change files
    loaded = []
    truncate = []
    removed_new = {}
    for src, _, dst, comp in moves:
        if src == "truncate":
            truncate.append(dst)
            continue
        loaded.append((src, dst, comp, src.read_bytes()))
    # the new archive's source is the active log: a removed new archive has no move
    for p in removals:
        p.unlink()
    for src, dst, comp, data in loaded:
        if src.name != dst.name and src.parent == logs and src != _active_of(src, logs, plans):
            src.unlink()
    for src, dst, comp, data in loaded:
        dst.write_bytes(gzip.compress(data, mtime=0) if comp else data)
    for p in truncate:
        p.write_bytes(b"")
    st = dict(state)
    st["streams"] = dict(state["streams"])
    st["streams"].update(new_state)
    from logkeep import state as state_mod
    state_mod.save(ctx.state_path, st)
    return out


def _active_of(src, logs, plans):
    for n, _, _ in plans:
        if src == logs / f"{n}.log":
            return src
    return None


def _first_line_time(log):
    try:
        with log.open("rb") as f:
            line = f.readline()
    except OSError:
        return None
    if b" " not in line:
        return None
    token = line.split(b" ", 1)[0]
    try:
        text = token.decode("ascii")
    except UnicodeDecodeError:
        return None
    return parse_time(text, False)
